import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import {
  AlertCircle, Archive, ArrowLeft, ArrowRight, Bell, Check, CheckCircle2,
  ClipboardList, Clock3, Fingerprint, Gauge, ImagePlus, Info,
  Loader2, LockKeyhole, LogIn, LogOut, MapPin, Menu,
  Pencil, Plus, RefreshCw, Search, Send, ShieldCheck, Siren, SlidersHorizontal,
  Sparkles, Upload, UserRound, Users, X, XCircle, Eye, Activity as ActivityIcon,
} from 'lucide-react';
import {
  AlertStatus, CaseStatus, ReviewStatus, SightingStatus, UserRole,
  getGetDashboardSummaryQueryKey, getGetMissingPersonQueryKey, getGetPublicOverviewQueryKey, getListAlertsQueryKey, getListMatchesQueryKey,
  getListMissingPersonsQueryKey, getListSightingsQueryKey, useArchiveMissingPerson,
  useCreateMissingPerson, useCreatePhotoMatch, useCreateSighting, useGetDashboardActivity,
  useGetDashboardSummary, useGetMissingPerson, useGetPublicOverview, useGetSighting,
  useHealthCheck, useListAlerts, useListMatches, useListMissingPersons, useListSightings,
  useLogin, useRegister, useUpdateAlert, useUpdateMatch, useUpdateMissingPerson,
  useUpdateSighting, setAuthTokenGetter,
  type Alert, type CaseStatus as CaseStatusType, type MatchCandidate, type MissingPerson,
  type Sighting, type SightingStatus as SightingStatusType,
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { Link, Route, Router as WouterRouter, Switch, useLocation, useParams } from 'wouter';

const queryClient = new QueryClient();
setAuthTokenGetter(() => localStorage.getItem('sentinel_token'));

const cx = (...classes: Array<string | false | null | undefined>) => classes.filter(Boolean).join(' ');
const fmtDate = (value?: string | null) => value ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) : '—';
const fmtTime = (value?: string | null) => value ? new Intl.DateTimeFormat('en', { hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : '—';
const initials = (name?: string | null) => (name ?? 'SP').split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase();

function Logo({ light = false }: { light?: boolean }) {
  return <Link href="/" data-testid="link-logo" className="flex items-center gap-3 group">
    <span className={cx('flex h-9 w-9 items-center justify-center rounded-lg border', light ? 'border-[#d9c98d]/50 bg-[#d9c98d]/10' : 'border-[#d6a84b]/40 bg-[#d6a84b]/10')}>
      <Fingerprint className={cx('h-5 w-5', light ? 'text-[#e4c76b]' : 'text-[#b07b17]')} />
    </span>
    <span className={cx('text-lg font-bold tracking-[.18em]', light ? 'text-[#f6f1df]' : 'text-[#18304d]')}>SENTINEL</span>
  </Link>;
}

function Button({ children, variant = 'primary', className, ...props }: { children: ReactNode; variant?: 'primary' | 'outline' | 'quiet' | 'danger' | 'gold'; className?: string } & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return <button className={cx('inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-4 text-sm font-semibold transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d6a84b]/60 disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-[#18304d] text-[#f7f1df] hover:bg-[#274461]', variant === 'gold' && 'bg-[#d6a84b] text-[#172941] hover:bg-[#e4bd69]', variant === 'outline' && 'border border-[#cfc6ad] bg-transparent text-[#18304d] hover:border-[#d6a84b] hover:bg-[#f7f0dc]', variant === 'quiet' && 'text-[#536579] hover:bg-[#eae6d9] hover:text-[#18304d]', variant === 'danger' && 'bg-[#a6473d] text-[#fff7ed] hover:bg-[#8f3831]', className)} {...props}>{children}</button>;
}

function StatusPill({ value }: { value?: string | null }) {
  const key = value ?? 'Unknown';
  const color = key.includes('Found') || key.includes('Verified') || key.includes('Confirmed') || key.includes('Resolved') ? 'bg-[#dcebe2] text-[#286246]' :
    key.includes('Rejected') || key.includes('Dismissed') || key.includes('Closed') ? 'bg-[#f1dfdc] text-[#91463e]' :
    key.includes('Review') || key.includes('Investigation') || key.includes('Viewed') || key.includes('Under') ? 'bg-[#f5e9c8] text-[#86651c]' : 'bg-[#e4e9ee] text-[#42576a]';
  return <span data-testid={`status-${key.toLowerCase().replaceAll(' ', '-')}`} className={cx('inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold', color)}>{key}</span>;
}

function QueryState({ loading, error, empty, onRetry, children }: { loading?: boolean; error?: boolean; empty?: boolean; onRetry?: () => void; children?: ReactNode }) {
  if (loading) return <div className="space-y-3" data-testid="state-loading">{[1, 2, 3].map((n) => <div key={n} className="h-16 animate-pulse rounded-lg bg-[#e9e5da]" />)}</div>;
  if (error) return <div className="rounded-xl border border-[#e2c6be] bg-[#fbefec] p-8 text-center" data-testid="state-error"><AlertCircle className="mx-auto mb-3 h-7 w-7 text-[#a6473d]" /><h3 className="font-bold text-[#713d39]">We couldn't load this view</h3><p className="mt-1 text-sm text-[#8b625d]">The service may be briefly unavailable.</p><Button variant="outline" className="mt-4" onClick={onRetry} data-testid="button-retry"><RefreshCw className="h-4 w-4" /> Try again</Button></div>;
  if (empty) return <div className="rounded-xl border border-dashed border-[#cfc6ad] bg-[#faf8f1] p-12 text-center" data-testid="state-empty"><ClipboardList className="mx-auto mb-3 h-8 w-8 text-[#a79e8b]" /><h3 className="font-bold text-[#33485d]">No records in this view</h3><p className="mt-1 text-sm text-[#788594]">New activity will appear here as it arrives.</p></div>;
  return <>{children}</>;
}

function PublicHeader() {
  return <header className="border-b border-[#ddd6c6] bg-[#faf8f1]/90 backdrop-blur">
    <div className="mx-auto flex h-[72px] max-w-7xl items-center justify-between px-5 lg:px-8">
      <Logo />
      <nav className="hidden items-center gap-7 text-sm font-semibold text-[#536579] md:flex">
        <Link href="/missing-persons" className="hover:text-[#18304d]" data-testid="link-directory">Case directory</Link>
        <Link href="/report-sighting" className="hover:text-[#18304d]" data-testid="link-report">Report a sighting</Link>
        <Link href="/photo-search" className="hover:text-[#18304d]" data-testid="link-photo-search">Photo review</Link>
      </nav>
      <div className="flex items-center gap-2">
        <Link href="/login" className="hidden px-3 py-2 text-sm font-semibold text-[#536579] hover:text-[#18304d] sm:block" data-testid="link-login">Staff sign in</Link>
        <Link href="/report-sighting" className="inline-flex min-h-10 items-center rounded-md bg-[#18304d] px-3.5 text-sm font-semibold text-[#f7f1df] hover:bg-[#274461]" data-testid="link-report-header"><Siren className="mr-2 h-4 w-4 text-[#d6a84b]" /> Report sighting</Link>
      </div>
    </div>
  </header>;
}

const navItems = [
  { href: '/dashboard', label: 'Overview', icon: Gauge },
  { href: '/cases', label: 'Cases', icon: ClipboardList },
  { href: '/sightings', label: 'Sightings', icon: Eye },
  { href: '/matches', label: 'Match review', icon: Sparkles },
  { href: '/alerts', label: 'Alerts', icon: Bell },
  { href: '/activity', label: 'Activity', icon: ActivityIcon },
];

function StaffShell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [open, setOpen] = useState(false);
  const [user, setUser] = useState(() => { try { return JSON.parse(localStorage.getItem('sentinel_user') ?? 'null'); } catch { return null; } });
  const summary = useGetDashboardSummary();
  const hasToken = Boolean(localStorage.getItem('sentinel_token'));
  useEffect(() => { if (!hasToken) setLocation('/login'); }, [hasToken, setLocation]);
  const logout = () => { localStorage.removeItem('sentinel_token'); localStorage.removeItem('sentinel_user'); setUser(null); setLocation('/'); };
  if (!hasToken) return <div className="min-h-[100dvh] bg-[#f3f0e8]" />;
  return <div className="min-h-[100dvh] bg-[#f3f0e8]">
    <aside className={cx('fixed inset-y-0 left-0 z-30 flex w-[248px] flex-col bg-[#18304d] text-[#f7f1df] transition-transform lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex h-[88px] items-center border-b border-[#36506b] px-6"><Logo light /><button className="ml-auto text-[#bdcad4] lg:hidden" onClick={() => setOpen(false)} data-testid="button-close-menu"><X className="h-5 w-5" /></button></div>
       <div className="px-4 pt-6"><p className="eyebrow mb-3 px-3 text-[#9faebe]">Operations room</p><nav className="space-y-1">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} className={cx('flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-medium transition-colors', location === href ? 'bg-[#d6a84b] text-[#172941]' : 'text-[#c6d0d9] hover:bg-[#29435f] hover:text-[#fbf5e7]')} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon className="h-[17px] w-[17px]" />{label}{label === 'Alerts' && (summary.data?.openAlerts ?? 0) > 0 && <span className="ml-auto rounded-full bg-[#a6473d] px-1.5 py-0.5 text-[10px] text-white">{summary.data?.openAlerts}</span>}</Link>)}</nav></div>
      <div className="mt-auto border-t border-[#36506b] p-4">
        <Link href="/profile" className="mb-2 flex items-center gap-3 rounded-md px-3 py-2.5 hover:bg-[#29435f]" data-testid="link-profile"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d6a84b] text-xs font-bold text-[#172941]">{initials(user?.name ?? 'Investigator')}</span><span className="min-w-0"><span className="block truncate text-sm font-semibold">{user?.name ?? 'Investigator'}</span><span className="block text-xs text-[#aebdca]">{user?.role ?? 'INVESTIGATOR'}</span></span></Link>
        <button onClick={logout} className="flex w-full items-center gap-3 rounded-md px-3 py-2 text-sm text-[#b5c3ce] hover:bg-[#29435f] hover:text-white" data-testid="button-logout"><LogOut className="h-4 w-4" /> Sign out</button>
      </div>
    </aside>
    {open && <button className="fixed inset-0 z-20 bg-[#152c45]/40 lg:hidden" onClick={() => setOpen(false)} data-testid="button-overlay" />}
    <main className="lg:pl-[248px]"><header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-[#ddd6c6] bg-[#f3f0e8]/95 px-5 backdrop-blur lg:px-8"><div className="flex items-center gap-3"><button className="rounded-md p-2 text-[#536579] hover:bg-[#e6e1d5] lg:hidden" onClick={() => setOpen(true)} data-testid="button-open-menu"><Menu className="h-5 w-5" /></button><div><p className="eyebrow text-[#8d806e]">Sentinel / {location.replace('/', '').replaceAll('/', ' / ') || 'overview'}</p></div></div><div className="flex items-center gap-4"><span className="hidden items-center gap-2 text-xs text-[#68798a] sm:flex"><span className="pulse-dot h-2 w-2 rounded-full bg-[#4c8b69]" /> Systems operational</span><Link href="/profile" className="text-[#536579] hover:text-[#18304d]" data-testid="link-top-profile"><UserRound className="h-5 w-5" /></Link></div></header><div className="page-in mx-auto max-w-[1440px] px-5 py-7 lg:px-8 lg:py-9">{children}</div></main>
  </div>;
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow mb-2 text-[#a17a2b]">{eyebrow}</p><h1 className="text-3xl font-bold tracking-[-.035em] text-[#18304d] lg:text-[38px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#68798a]">{description}</p>}</div>{action}</div>;
}

function StatTile({ label, value, detail, icon: Icon, tone = 'navy' }: { label: string; value?: number | string; detail?: string; icon: typeof Gauge; tone?: 'navy' | 'gold' | 'red' | 'green' }) {
  const tones = { navy: 'bg-[#18304d] text-[#f7f1df]', gold: 'bg-[#d6a84b] text-[#172941]', red: 'bg-[#a6473d] text-[#fff7ed]', green: 'bg-[#43775b] text-[#f3f7ed]' };
  return <div className={cx('relative overflow-hidden rounded-xl p-5', tones[tone])} data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><p className="eyebrow opacity-75">{label}</p><Icon className="h-5 w-5 opacity-70" /></div><p className="mt-4 text-4xl font-bold tracking-[-.04em]">{value ?? '—'}</p>{detail && <p className="mt-1 text-xs opacity-75">{detail}</p>}<span className="absolute -bottom-8 -right-5 h-24 w-24 rounded-full border-[14px] border-current opacity-[.08]" /></div>;
}

function Landing() {
  const { data: overview, isLoading: overviewLoading } = useGetPublicOverview();
  const { data: health } = useHealthCheck();
  return <div className="noise min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main>
    <section className="signal-grid relative overflow-hidden border-b border-[#ddd6c6]"><div className="mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-[1.1fr_.9fr] lg:items-center lg:px-8 lg:py-28"><div className="relative z-10"><div className="mb-6 flex items-center gap-3"><span className="pulse-dot h-2.5 w-2.5 rounded-full bg-[#d6a84b]" /><span className="eyebrow text-[#8b6b2a]">A public safety coordination service</span></div><h1 className="max-w-3xl text-[clamp(3.1rem,7vw,6.8rem)] font-bold leading-[.91] tracking-[-.075em] text-[#18304d]">Every detail<br /><span className="text-[#a17a2b]">matters.</span></h1><p className="mt-8 max-w-xl text-lg leading-8 text-[#5b6b7d]">Sentinel helps communities and investigators coordinate the careful work of bringing missing people home. Share what you know. Let trained reviewers connect the signals.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/missing-persons" className="inline-flex min-h-12 items-center gap-2 rounded-md bg-[#18304d] px-5 text-sm font-bold text-[#f7f1df] hover:bg-[#274461]" data-testid="link-explore-cases">Explore public cases <ArrowRight className="h-4 w-4 text-[#d6a84b]" /></Link><Link href="/report-sighting" className="inline-flex min-h-12 items-center gap-2 rounded-md border border-[#cfc6ad] px-5 text-sm font-bold text-[#18304d] hover:border-[#d6a84b] hover:bg-[#f5efdf]" data-testid="link-share-sighting">Share a sighting</Link></div></div><div className="relative mx-auto w-full max-w-[440px]"><div className="rounded-2xl border border-[#ddd0ad] bg-[#f5edda] p-5 shadow-[0_20px_60px_rgba(35,51,76,.1)]"><div className="flex items-center justify-between border-b border-[#dfd2b5] pb-4"><div className="flex items-center gap-2"><ShieldCheck className="h-5 w-5 text-[#a17a2b]" /><span className="text-sm font-bold text-[#18304d]">Sentinel network</span></div><span className="mono text-[10px] text-[#8e7e63]">{health?.status === 'ok' ? 'LIVE' : 'SECURE'}</span></div><div className="space-y-3 py-4"><div className="rounded-lg bg-[#fbf8ed] p-4"><div className="flex justify-between"><span className="eyebrow text-[#83765e]">Review protocol</span><CheckCircle2 className="h-4 w-4 text-[#4c8b69]" /></div><p className="mt-2 text-sm font-semibold text-[#32485e]">Human review before action</p><p className="mt-1 text-xs leading-5 text-[#788594]">Possible matches are signals, never conclusions.</p></div><div className="grid grid-cols-2 gap-3">{[['Active cases', overview?.activeCases], ['Sightings shared', overview?.reportedSightings]].map(([label, value]) => <div key={String(label)} className="rounded-lg border border-[#e2d8bf] p-3"><span className="eyebrow text-[#83765e]">{label}</span><p className="mt-2 text-2xl font-bold text-[#18304d]">{overviewLoading ? '—' : value}</p></div>)}</div></div><p className="eyebrow text-[#8e7e63]">Connection secured · community to command</p></div><div className="absolute -right-8 -top-8 h-20 w-20 rounded-full border border-[#d6a84b]/50" /><div className="absolute -bottom-6 -left-8 h-14 w-14 rounded-full bg-[#d6a84b]/20" /></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-20 lg:px-8"><div className="grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><p className="eyebrow text-[#a17a2b]">How to help</p><h2 className="mt-3 text-3xl font-bold tracking-tight text-[#18304d]">Useful information<br />moves carefully.</h2></div><div className="grid gap-4 sm:grid-cols-3">{[['01', 'Browse cases', 'See only the information families and investigators have intentionally made public.'], ['02', 'Report clearly', 'A place, a time, and what you observed can give a team its next lead.'], ['03', 'Protect people', 'Do not confront anyone or post sensitive details. Contact emergency services first.']].map(([n, title, copy]) => <div key={n} className="border-l-2 border-[#d6a84b] pl-5"><span className="mono text-xs text-[#a17a2b]">{n}</span><h3 className="mt-3 font-bold text-[#18304d]">{title}</h3><p className="mt-2 text-sm leading-6 text-[#68798a]">{copy}</p></div>)}</div></div></section>
    <section className="border-y border-[#ddd6c6] bg-[#f1eee5]"><div className="mx-auto flex max-w-7xl flex-col gap-6 px-5 py-10 sm:flex-row sm:items-center sm:justify-between lg:px-8"><div className="flex gap-4"><Info className="mt-1 h-5 w-5 shrink-0 text-[#a17a2b]" /><div><h2 className="font-bold text-[#18304d]">If someone is in immediate danger</h2><p className="mt-1 text-sm text-[#68798a]">Call your local emergency number. Sentinel is not an emergency response service.</p></div></div><Link href="/report-sighting" className="inline-flex items-center gap-2 text-sm font-bold text-[#8b6b2a] hover:text-[#18304d]" data-testid="link-safety-report">Read reporting guidance <ArrowRight className="h-4 w-4" /></Link></div></section>
  </main><footer className="mx-auto flex max-w-7xl flex-col gap-3 px-5 py-8 text-xs text-[#788594] sm:flex-row sm:items-center sm:justify-between lg:px-8"><span>Sentinel public access · Built for careful coordination</span><span className="mono">No identification by automation alone</span></footer></div>;
}

function Directory() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState<CaseStatusType | undefined>();
  const params = useMemo(() => ({ search: search || undefined, status, limit: 50 }), [search, status]);
  const query = useListMissingPersons(params);
  const persons = query.data ?? [];
  return <div className="min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8"><PageTitle eyebrow="Public case directory" title="People still being sought" description="These summaries are intentionally public. If you have information about one of these cases, please share it with investigators." action={<span className="mono text-xs text-[#8d806e]">{persons.length} records returned</span>} /><div className="mb-8 flex flex-col gap-3 rounded-xl border border-[#ddd6c6] bg-[#f3f0e8] p-3 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-[#8d806e]" /><input value={search} onChange={(e) => setSearch(e.target.value)} className="field pl-10" placeholder="Search by name or location" data-testid="input-search-cases" /></label><select value={status ?? ''} onChange={(e) => setStatus((e.target.value || undefined) as CaseStatusType | undefined)} className="field sm:w-52" data-testid="select-case-status"><option value="">All case statuses</option>{Object.values(CaseStatus).map((s) => <option key={s} value={s}>{s}</option>)}</select></div><QueryState loading={query.isLoading} error={query.isError} empty={!query.isLoading && !query.isError && persons.length === 0} onRetry={() => query.refetch()}><div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{persons.map((person) => <CaseCard key={person.id} person={person} />)}</div></QueryState></main></div>;
}

function CaseCard({ person }: { person: MissingPerson }) {
  return <Link href={`/missing-persons/${person.id}`} className="card-lift group flex overflow-hidden rounded-xl border border-[#ddd6c6] bg-[#fffdf8]" data-testid={`card-case-${person.id}`}><div className="flex h-36 w-28 shrink-0 items-center justify-center overflow-hidden bg-[#dfe3e3]">{person.imageUrl ? <img src={person.imageUrl} alt={`Public file photo of ${person.fullName}`} className="h-full w-full object-cover grayscale-[.15]" data-testid={`img-case-${person.id}`} /> : <span className="text-2xl font-bold text-[#82909a]">{initials(person.fullName)}</span>}</div><div className="min-w-0 flex-1 p-4"><div className="flex items-start justify-between gap-2"><StatusPill value={person.status} /><ArrowRight className="h-4 w-4 shrink-0 text-[#a79e8b] transition-transform group-hover:translate-x-1" /></div><h3 className="mt-3 truncate font-bold text-[#18304d]" data-testid={`text-case-name-${person.id}`}>{person.fullName}</h3><p className="mt-1 text-xs text-[#68798a]">{person.age} · {person.gender}</p><p className="mt-3 flex items-center gap-1 truncate text-xs text-[#8d806e]"><MapPin className="h-3.5 w-3.5" />{person.lastKnownLocation}</p><p className="mt-1 mono text-[10px] text-[#a79e8b]">Missing since {fmtDate(person.missingDate)}</p></div></Link>;
}

function CaseDetail() {
  const { id } = useParams<{ id: string }>(); const caseId = Number(id);
  const query = useGetMissingPerson(caseId); const person = query.data;
  return <div className="min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main className="mx-auto max-w-5xl px-5 py-10 lg:px-8"><Link href="/missing-persons" className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-[#68798a] hover:text-[#18304d]" data-testid="link-back-directory"><ArrowLeft className="h-4 w-4" /> Back to directory</Link><QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{person && <><div className="grid gap-8 md:grid-cols-[280px_1fr]"><div className="flex aspect-[4/5] items-center justify-center overflow-hidden rounded-xl border border-[#ddd6c6] bg-[#dfe3e3]">{person.imageUrl ? <img src={person.imageUrl} alt={`Public file photo of ${person.fullName}`} className="h-full w-full object-cover" data-testid="img-case-detail" /> : <span className="text-5xl font-bold text-[#82909a]">{initials(person.fullName)}</span>}</div><div><div className="flex flex-wrap items-center gap-3"><StatusPill value={person.status} /><span className="mono text-[10px] text-[#8d806e]">CASE #{String(person.id).padStart(5, '0')}</span></div><h1 className="mt-4 text-4xl font-bold tracking-[-.05em] text-[#18304d]">{person.fullName}</h1><p className="mt-3 text-[#68798a]">{person.age} years old · {person.gender}{person.height ? ` · ${person.height}` : ''}</p><div className="mt-7 grid gap-4 border-y border-[#ddd6c6] py-5 sm:grid-cols-2"><div><span className="eyebrow text-[#a17a2b]">Last known location</span><p className="mt-1 flex items-center gap-2 text-sm font-semibold text-[#33485d]"><MapPin className="h-4 w-4 text-[#a17a2b]" />{person.lastKnownLocation}</p></div><div><span className="eyebrow text-[#a17a2b]">Missing since</span><p className="mt-1 text-sm font-semibold text-[#33485d]">{fmtDate(person.missingDate)}</p></div></div><p className="mt-6 max-w-xl text-[15px] leading-7 text-[#536579]">{person.description || 'No public description has been provided for this case.'}</p><Link href={`/report-sighting?case=${person.id}`} className="mt-7 inline-flex min-h-11 items-center gap-2 rounded-md bg-[#18304d] px-5 text-sm font-bold text-[#f7f1df] hover:bg-[#274461]" data-testid="link-report-case"><Siren className="h-4 w-4 text-[#d6a84b]" /> Report information</Link></div></div><div className="mt-12 grid gap-6 md:grid-cols-2"><div className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><p className="eyebrow text-[#a17a2b]">Identification notes</p><p className="mt-3 text-sm leading-7 text-[#536579]">{person.identificationMarks || 'No public identification marks have been supplied.'}</p></div><div className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><p className="eyebrow text-[#a17a2b]">Additional information</p><p className="mt-3 text-sm leading-7 text-[#536579]">{person.additionalInformation || 'No additional public information has been supplied.'}</p></div></div><div className="mt-8 rounded-xl border border-[#dfd2b5] bg-[#f5edda] p-5"><div className="flex gap-3"><Info className="h-5 w-5 shrink-0 text-[#a17a2b]" /><p className="text-sm leading-6 text-[#5b5d55]">Please do not approach or confront anyone. Submit observations through Sentinel or contact local authorities.</p></div></div></>}</QueryState></main></div>;
}

function Field({ label, name, value, onChange, type = 'text', required = false, placeholder }: { label: string; name: string; value: string; onChange: (value: string) => void; type?: string; required?: boolean; placeholder?: string }) {
  return <label className="block"><span className="mb-1.5 block text-sm font-semibold text-[#33485d]">{label}{required && <span className="text-[#a6473d]"> *</span>}</span><input name={name} value={value} onChange={(e) => onChange(e.target.value)} type={type} required={required} placeholder={placeholder} className="field" data-testid={`input-${name}`} /></label>;
}
function TextArea({ label, name, value, onChange, required = false, placeholder }: { label: string; name: string; value: string; onChange: (value: string) => void; required?: boolean; placeholder?: string }) {
  return <label className="block"><span className="mb-1.5 block text-sm font-semibold text-[#33485d]">{label}{required && <span className="text-[#a6473d]"> *</span>}</span><textarea name={name} value={value} onChange={(e) => onChange(e.target.value)} required={required} placeholder={placeholder} rows={4} className="field resize-y" data-testid={`input-${name}`} /></label>;
}

function ReportSighting() {
  const create = useCreateSighting(); const qc = useQueryClient(); const [done, setDone] = useState<{ message: string; id?: number } | null>(null); const [error, setError] = useState('');
  const [form, setForm] = useState({ location: '', sightingDate: '', description: '', reporterName: '', reporterContact: '', imageUrl: '' });
  const set = (key: keyof typeof form) => (value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); create.mutate({ data: { ...form, imageUrl: form.imageUrl || undefined, reporterName: form.reporterName || undefined, reporterContact: form.reporterContact || undefined } }, { onSuccess: (result) => { qc.invalidateQueries({ queryKey: getListSightingsQueryKey() }); qc.invalidateQueries({ queryKey: getGetPublicOverviewQueryKey() }); setDone({ message: result.message, id: result.sighting.id }); }, onError: () => setError('We could not submit this report. Please check the details and try again.') }); };
  if (done) return <div className="min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main className="mx-auto flex max-w-2xl flex-col items-center px-5 py-24 text-center"><span className="flex h-16 w-16 items-center justify-center rounded-full bg-[#dcebe2]"><CheckCircle2 className="h-8 w-8 text-[#367051]" /></span><p className="eyebrow mt-7 text-[#a17a2b]">Report received</p><h1 className="mt-3 text-4xl font-bold tracking-tight text-[#18304d]">Thank you for sharing what you saw.</h1><p className="mt-5 max-w-lg leading-7 text-[#68798a]">{done.message || 'Your report is now available to trained reviewers.'}</p><div className="mt-8 rounded-lg bg-[#f3f0e8] px-5 py-3 mono text-xs text-[#536579]">Reference {done.id ? `SG-${String(done.id).padStart(6, '0')}` : 'created'}</div><Link href="/" className="mt-8 text-sm font-bold text-[#8b6b2a]" data-testid="link-return-home">Return to Sentinel</Link></main></div>;
  return <div className="min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main className="mx-auto max-w-3xl px-5 py-12 lg:px-8"><Link href="/" className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-[#68798a]" data-testid="link-back-home"><ArrowLeft className="h-4 w-4" /> Back</Link><PageTitle eyebrow="Community report" title="Report a sighting" description="Share what you observed. Specific, firsthand details help reviewers assess the report quickly." /><div className="mb-8 flex gap-3 rounded-xl border border-[#dfd2b5] bg-[#f5edda] p-5"><ShieldCheck className="h-5 w-5 shrink-0 text-[#a17a2b]" /><div className="text-sm leading-6 text-[#5b5d55]"><strong className="text-[#33485d]">Your safety comes first.</strong> Do not approach anyone or put yourself at risk. For immediate danger, call local emergency services.</div></div><form onSubmit={submit} className="space-y-6 rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-5 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><Field label="Where did you see them?" name="location" value={form.location} onChange={set('location')} required placeholder="Street, venue, or landmark" /><Field label="When did you see them?" name="sightingDate" value={form.sightingDate} onChange={set('sightingDate')} required type="datetime-local" /></div><TextArea label="What did you observe?" name="description" value={form.description} onChange={set('description')} required placeholder="Describe clothing, direction of travel, companions, or anything else you remember." /><div className="grid gap-5 sm:grid-cols-2"><Field label="Your name" name="reporterName" value={form.reporterName} onChange={set('reporterName')} placeholder="Optional" /><Field label="How can reviewers reach you?" name="reporterContact" value={form.reporterContact} onChange={set('reporterContact')} placeholder="Email or phone (optional)" /></div><Field label="Photo URL" name="imageUrl" value={form.imageUrl} onChange={set('imageUrl')} placeholder="Optional secure image link" />{error && <p className="rounded-md bg-[#fbefec] p-3 text-sm text-[#91463e]" data-testid="status-submit-error">{error}</p>}<div className="flex flex-col-reverse justify-between gap-3 border-t border-[#e7e0d2] pt-5 sm:flex-row sm:items-center"><p className="text-xs leading-5 text-[#788594]">By submitting, you confirm this is a good-faith report.</p><Button type="submit" disabled={create.isPending} data-testid="button-submit-sighting">{create.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />} {create.isPending ? 'Sending report…' : 'Submit report'}</Button></div></form></main></div>;
}

function PhotoSearch() {
  const create = useCreatePhotoMatch(); const [imageUrl, setImageUrl] = useState(''); const [result, setResult] = useState<{ message: string; candidates: MatchCandidate[] } | null>(null); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); create.mutate({ data: { imageUrl } }, { onSuccess: setResult, onError: () => setError('We could not process this photo. Please try another image link.') }); };
  return <div className="min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main className="mx-auto max-w-4xl px-5 py-12 lg:px-8"><PageTitle eyebrow="Assisted photo review" title="Submit a photo for review" description="Sentinel can return ranked possibilities for trained human review. It does not identify people or establish identity." /><div className="grid gap-6 md:grid-cols-[.8fr_1.2fr]"><form onSubmit={submit} className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><div className="flex h-40 flex-col items-center justify-center rounded-lg border border-dashed border-[#cfc6ad] bg-[#f5f1e7] text-center"><ImagePlus className="h-8 w-8 text-[#a79e8b]" /><p className="mt-2 text-sm font-semibold text-[#536579]">Photo input</p><p className="mt-1 text-xs text-[#8d806e]">Use an authorized image URL</p></div><label className="mt-5 block"><span className="mb-1.5 block text-sm font-semibold text-[#33485d]">Image URL <span className="text-[#a6473d]">*</span></span><input value={imageUrl} onChange={(e) => setImageUrl(e.target.value)} required className="field" placeholder="https://…" data-testid="input-image-url" /></label>{error && <p className="mt-3 text-sm text-[#91463e]" data-testid="status-photo-error">{error}</p>}<Button type="submit" className="mt-5 w-full" disabled={create.isPending} data-testid="button-submit-photo">{create.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />} {create.isPending ? 'Reviewing photo…' : 'Request possible matches'}</Button><p className="mt-4 text-center text-xs leading-5 text-[#8d806e]">Images are handled for review only. Never use this tool to confront someone.</p></form><div className="rounded-xl border border-[#ddd6c6] bg-[#f3f0e8] p-6"><div className="flex items-center justify-between"><p className="eyebrow text-[#a17a2b]">Possible matches</p>{result && <span className="mono text-[10px] text-[#8d806e]">{result.candidates.length} ranked</span>}</div>{!result ? <div className="flex h-56 flex-col items-center justify-center text-center"><Sparkles className="h-8 w-8 text-[#c5b78f]" /><p className="mt-3 text-sm font-semibold text-[#536579]">Results appear here</p><p className="mt-1 max-w-xs text-xs leading-5 text-[#8d806e]">Submit a clear photo to begin a careful, human-led review.</p></div> : <div><p className="my-4 text-sm leading-6 text-[#536579]">{result.message}</p><div className="space-y-3">{result.candidates.map((candidate, i) => <div key={candidate.missingPersonId} className="flex items-center gap-3 rounded-lg border border-[#ddd6c6] bg-[#fffdf8] p-3" data-testid={`card-photo-candidate-${candidate.missingPersonId}`}><span className="mono w-5 text-xs text-[#a17a2b]">0{i + 1}</span><div className="flex h-10 w-10 items-center justify-center overflow-hidden rounded-md bg-[#dfe3e3] text-xs font-bold text-[#82909a]">{candidate.imageUrl ? <img src={candidate.imageUrl} alt="" className="h-full w-full object-cover" /> : initials(candidate.fullName)}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-[#33485d]">{candidate.fullName}</p><p className="truncate text-xs text-[#8d806e]">{candidate.lastKnownLocation}</p></div><span className="mono text-sm font-bold text-[#a17a2b]">{candidate.confidenceScore.toFixed(1)}%</span></div>)}</div></div>}</div></div></main></div>;
}

function Dashboard() {
  const summary = useGetDashboardSummary(); const activity = useGetDashboardActivity(); const s = summary.data;
  return <><PageTitle eyebrow="Operational overview" title="Good morning, team." description="A focused read of open cases, incoming information, and review work." action={<span className="flex items-center gap-2 rounded-full bg-[#dcebe2] px-3 py-1.5 text-xs font-semibold text-[#367051]"><span className="pulse-dot h-2 w-2 rounded-full bg-[#4c8b69]" /> Live operations</span>} /><QueryState loading={summary.isLoading} error={summary.isError} onRetry={() => summary.refetch()}>{s && <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatTile label="Active cases" value={s.activeCases} detail={`${s.totalMissingPersons} total records`} icon={Users} /><StatTile label="Pending sightings" value={s.pendingSightings} detail={`${s.totalSightings} reports received`} icon={Eye} tone="gold" /><StatTile label="Possible matches" value={s.possibleMatches} detail={`${s.highConfidenceMatches} high confidence`} icon={Sparkles} tone="green" /><StatTile label="Open alerts" value={s.openAlerts} detail="Needs human attention" icon={Bell} tone="red" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><section className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><div className="flex items-center justify-between"><div><p className="eyebrow text-[#a17a2b]">Signal volume</p><h2 className="mt-1 text-lg font-bold text-[#18304d]">Sightings, last 7 days</h2></div><span className="mono text-[10px] text-[#8d806e]">REPORTS / DAY</span></div><MiniChart items={s.sightingsByDay} /></section><section className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><p className="eyebrow text-[#a17a2b]">Case distribution</p><h2 className="mt-1 text-lg font-bold text-[#18304d]">By status</h2><div className="mt-6 space-y-4">{s.casesByStatus.map((item) => <div key={item.label}><div className="mb-1 flex justify-between text-xs"><span className="font-semibold text-[#536579]">{item.label}</span><span className="mono text-[#8d806e]">{item.count}</span></div><div className="h-2 rounded-full bg-[#ebe7dc]"><div className="h-full rounded-full bg-[#d6a84b]" style={{ width: `${Math.min(100, (item.count / Math.max(1, s.totalMissingPersons)) * 100)}%` }} /></div></div>)}</div></section></div></>}</QueryState><section className="mt-6 rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><div className="mb-5 flex items-center justify-between"><div><p className="eyebrow text-[#a17a2b]">Audit trail</p><h2 className="mt-1 text-lg font-bold text-[#18304d]">Recent activity</h2></div><Link href="/activity" className="text-xs font-bold text-[#8b6b2a]" data-testid="link-view-activity">View all</Link></div><QueryState loading={activity.isLoading} error={activity.isError} empty={!activity.isLoading && !activity.isError && (activity.data ?? []).length === 0} onRetry={() => activity.refetch()}><ActivityList items={(activity.data ?? []).slice(0, 5)} /></QueryState></section></>;
}
function MiniChart({ items }: { items: { label: string; count: number }[] }) { const max = Math.max(1, ...items.map((i) => i.count)); return <div className="mt-7 flex h-44 items-end gap-2 border-b border-l border-[#e1dbcd] px-3 pb-0 pt-5">{items.map((item) => <div key={item.label} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="w-full max-w-9 rounded-t-sm bg-[#d6a84b] transition-all hover:bg-[#a17a2b]" style={{ height: `${Math.max(7, item.count / max * 100)}%` }} title={`${item.count} reports`} /><span className="mono text-[9px] text-[#8d806e]">{item.label.slice(0, 3)}</span></div>)}</div>; }
function ActivityList({ items }: { items: { id: number; action: string; entity: string; entityId: number; createdAt: string }[] }) { return <div className="divide-y divide-[#e7e0d2]">{items.map((item) => <div key={item.id} className="flex items-center gap-3 py-3" data-testid={`row-activity-${item.id}`}><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#e9edf0] text-[#536579]"><ActivityIcon className="h-4 w-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm text-[#33485d]"><strong>{item.action}</strong> · {item.entity} #{item.entityId}</p><p className="mono text-[10px] text-[#8d806e]">{fmtDate(item.createdAt)} · {fmtTime(item.createdAt)}</p></div></div>)}</div>; }

function Cases() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState<CaseStatusType | undefined>(); const [confirm, setConfirm] = useState<number | null>(null);
  const params = useMemo(() => ({ search: search || undefined, status, limit: 100 }), [search, status]); const query = useListMissingPersons(params); const archive = useArchiveMissingPerson(); const qc = useQueryClient();
  const doArchive = () => { if (confirm === null) return; archive.mutate({ id: confirm }, { onSuccess: () => { setConfirm(null); qc.invalidateQueries({ queryKey: getListMissingPersonsQueryKey() }); } }); };
  return <><PageTitle eyebrow="Case management" title="Missing-person cases" description="Maintain the public case record and coordinate the current status of every investigation." action={<Link href="/cases/new" className="inline-flex min-h-10 items-center gap-2 rounded-md bg-[#18304d] px-4 text-sm font-bold text-[#f7f1df]" data-testid="link-new-case"><Plus className="h-4 w-4 text-[#d6a84b]" /> Add case</Link>} /><div className="mb-6 flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-[#8d806e]" /><input value={search} onChange={(e) => setSearch(e.target.value)} className="field pl-10" placeholder="Search cases" data-testid="input-staff-case-search" /></label><select value={status ?? ''} onChange={(e) => setStatus((e.target.value || undefined) as CaseStatusType | undefined)} className="field sm:w-52" data-testid="select-staff-case-status"><option value="">All statuses</option>{Object.values(CaseStatus).map((s) => <option key={s} value={s}>{s}</option>)}</select></div><QueryState loading={query.isLoading} error={query.isError} empty={!query.isLoading && !query.isError && !(query.data ?? []).length} onRetry={() => query.refetch()}><div className="overflow-hidden rounded-xl border border-[#ddd6c6] bg-[#fffdf8]"><div className="scroll-thin overflow-x-auto"><table className="data-table w-full min-w-[760px] text-left"><thead className="bg-[#f3f0e8] text-[11px] uppercase tracking-wider text-[#8d806e]"><tr><th className="px-5 py-3 font-semibold">Person</th><th className="px-5 py-3 font-semibold">Location</th><th className="px-5 py-3 font-semibold">Missing since</th><th className="px-5 py-3 font-semibold">Status</th><th className="px-5 py-3 text-right font-semibold">Actions</th></tr></thead><tbody className="divide-y divide-[#e7e0d2]">{(query.data ?? []).map((person) => <tr key={person.id} data-testid={`row-case-${person.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-md bg-[#e4e9ee] text-xs font-bold text-[#536579]">{initials(person.fullName)}</span><div><p className="font-bold text-[#33485d]">{person.fullName}</p><p className="text-xs text-[#8d806e]">{person.age} · {person.gender}</p></div></div></td><td className="px-5 py-4 text-sm text-[#536579]">{person.lastKnownLocation}</td><td className="px-5 py-4 mono text-xs text-[#788594]">{fmtDate(person.missingDate)}</td><td className="px-5 py-4"><StatusPill value={person.status} /></td><td className="px-5 py-4"><div className="flex justify-end gap-1"><Link href={`/cases/${person.id}`} className="rounded p-2 text-[#536579] hover:bg-[#e9e5da]" data-testid={`link-edit-case-${person.id}`}><Pencil className="h-4 w-4" /></Link><button onClick={() => setConfirm(person.id)} className="rounded p-2 text-[#a6473d] hover:bg-[#f5e4e1]" data-testid={`button-archive-case-${person.id}`}><Archive className="h-4 w-4" /></button></div></td></tr>)}</tbody></table></div></div></QueryState>{confirm !== null && <ConfirmDialog title="Archive this case?" copy="The case will leave active staff queues and public listings." onCancel={() => setConfirm(null)} onConfirm={doArchive} loading={archive.isPending} />}</>;
}

function ConfirmDialog({ title, copy, onCancel, onConfirm, loading }: { title: string; copy: string; onCancel: () => void; onConfirm: () => void; loading?: boolean }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#172941]/40 p-5"><div className="w-full max-w-sm rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="eyebrow text-[#a17a2b]">Confirmation</p><h2 className="mt-2 text-xl font-bold text-[#18304d]">{title}</h2></div><button onClick={onCancel} className="text-[#8d806e]" data-testid="button-close-confirm"><X className="h-5 w-5" /></button></div><p className="mt-3 text-sm leading-6 text-[#68798a]">{copy}</p><div className="mt-6 flex justify-end gap-2"><Button variant="quiet" onClick={onCancel} data-testid="button-cancel-confirm">Cancel</Button><Button variant="danger" onClick={onConfirm} disabled={loading} data-testid="button-confirm-action">{loading && <Loader2 className="h-4 w-4 animate-spin" />} Archive</Button></div></div></div>; }

function CaseForm({ editId }: { editId?: number }) {
  const isEdit = !!editId; const existing = useGetMissingPerson(editId ?? 0, { query: { enabled: isEdit, queryKey: getGetMissingPersonQueryKey(editId ?? 0) } }); const create = useCreateMissingPerson(); const update = useUpdateMissingPerson(); const [, setLocation] = useLocation(); const [error, setError] = useState('');
  const [form, setForm] = useState({ fullName: '', age: '', gender: '', height: '', description: '', identificationMarks: '', lastKnownLocation: '', missingDate: '', contactInformation: '', additionalInformation: '', imageUrl: '' });
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { if (isEdit && existing.data && !loaded) { setForm({ fullName: existing.data.fullName, age: String(existing.data.age), gender: existing.data.gender, height: existing.data.height ?? '', description: existing.data.description ?? '', identificationMarks: existing.data.identificationMarks ?? '', lastKnownLocation: existing.data.lastKnownLocation, missingDate: existing.data.missingDate.slice(0, 10), contactInformation: existing.data.contactInformation ?? '', additionalInformation: existing.data.additionalInformation ?? '', imageUrl: existing.data.imageUrl ?? '' }); setLoaded(true); } }, [existing.data, isEdit, loaded]);
  const set = (key: keyof typeof form) => (value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); const payload = { ...form, age: Number(form.age), imageUrl: form.imageUrl || undefined }; if (isEdit) update.mutate({ id: editId!, data: payload }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListMissingPersonsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetMissingPersonQueryKey(editId!) }); setLocation('/cases'); }, onError: () => setError('Unable to update this case.') }); else create.mutate({ data: payload }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListMissingPersonsQueryKey() }); setLocation('/cases'); }, onError: () => setError('Unable to create this case.') }); };
  return <><PageTitle eyebrow={isEdit ? 'Case record' : 'New case'} title={isEdit ? 'Edit case' : 'Add a missing-person case'} description="Keep the record factual, current, and limited to information appropriate for the intended audience." action={<Link href="/cases" className="inline-flex items-center gap-2 text-sm font-semibold text-[#68798a]" data-testid="link-cancel-case"><ArrowLeft className="h-4 w-4" /> Cancel</Link>} /><QueryState loading={isEdit && existing.isLoading} error={isEdit && existing.isError} onRetry={() => existing.refetch()}><form onSubmit={submit} className="max-w-4xl space-y-7 rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-5 sm:p-8"><div><p className="eyebrow text-[#a17a2b]">Identity and status</p><div className="mt-4 grid gap-5 sm:grid-cols-2"><Field label="Full name" name="fullName" value={form.fullName} onChange={set('fullName')} required /><Field label="Age" name="age" type="number" value={form.age} onChange={set('age')} required /><Field label="Gender" name="gender" value={form.gender} onChange={set('gender')} required /><Field label="Height" name="height" value={form.height} onChange={set('height')} /></div></div><div className="border-t border-[#e7e0d2] pt-7"><p className="eyebrow text-[#a17a2b]">Last known information</p><div className="mt-4 grid gap-5 sm:grid-cols-2"><Field label="Last known location" name="lastKnownLocation" value={form.lastKnownLocation} onChange={set('lastKnownLocation')} required /><Field label="Missing date" name="missingDate" type="date" value={form.missingDate} onChange={set('missingDate')} required /></div><div className="mt-5"><TextArea label="Description" name="description" value={form.description} onChange={set('description')} /></div><div className="mt-5"><TextArea label="Identification marks" name="identificationMarks" value={form.identificationMarks} onChange={set('identificationMarks')} /></div></div><div className="border-t border-[#e7e0d2] pt-7"><p className="eyebrow text-[#a17a2b]">Contact and media</p><div className="mt-4 grid gap-5 sm:grid-cols-2"><TextArea label="Contact information" name="contactInformation" value={form.contactInformation} onChange={set('contactInformation')} /><TextArea label="Additional information" name="additionalInformation" value={form.additionalInformation} onChange={set('additionalInformation')} /></div><div className="mt-5"><Field label="Primary image URL" name="imageUrl" value={form.imageUrl} onChange={set('imageUrl')} /></div></div>{error && <p className="rounded-md bg-[#fbefec] p-3 text-sm text-[#91463e]" data-testid="status-case-form-error">{error}</p>}<div className="flex justify-end border-t border-[#e7e0d2] pt-5"><Button type="submit" disabled={create.isPending || update.isPending} data-testid="button-save-case">{(create.isPending || update.isPending) && <Loader2 className="h-4 w-4 animate-spin" />} {isEdit ? 'Save case changes' : 'Create case record'}</Button></div></form></QueryState></>;
}

function Sightings() {
  const [status, setStatus] = useState<SightingStatusType | undefined>(); const query = useListSightings({ status, limit: 100 }); const update = useUpdateSighting(); const qc = useQueryClient();
  const setStatusFor = (id: number, next: SightingStatusType) => update.mutate({ id, data: { status: next } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListSightingsQueryKey() }) });
  return <><PageTitle eyebrow="Human review queue" title="Sighting reports" description="Triage incoming observations, attach them to a case, and keep review decisions explicit." action={<select value={status ?? ''} onChange={(e) => setStatus((e.target.value || undefined) as SightingStatusType | undefined)} className="field sm:w-48" data-testid="select-sighting-status"><option value="">All statuses</option>{Object.values(SightingStatus).map((s) => <option key={s} value={s}>{s}</option>)}</select>} /><QueryState loading={query.isLoading} error={query.isError} empty={!query.isLoading && !query.isError && !(query.data ?? []).length} onRetry={() => query.refetch()}><div className="space-y-3">{(query.data ?? []).map((sighting) => <SightingRow key={sighting.id} sighting={sighting} onStatus={setStatusFor} pending={update.isPending} />)}</div></QueryState></>;
}
function SightingRow({ sighting, onStatus, pending }: { sighting: Sighting; onStatus: (id: number, status: SightingStatusType) => void; pending: boolean }) { return <article className="card-lift rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-5" data-testid={`card-sighting-${sighting.id}`}><div className="flex flex-col gap-4 md:flex-row md:items-start"><div className="flex h-20 w-20 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-[#e4e9ee] text-xl font-bold text-[#82909a]">{sighting.imageUrl ? <img src={sighting.imageUrl} alt="" className="h-full w-full object-cover" /> : initials(sighting.reporterName)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="mono text-[10px] text-[#a17a2b]">SG-{String(sighting.id).padStart(6, '0')}</span><StatusPill value={sighting.status} />{sighting.topMatchScore != null && <span className="rounded-full bg-[#e8efe9] px-2 py-1 mono text-[10px] font-bold text-[#367051]">{sighting.topMatchScore.toFixed(1)}% match</span>}</div><h2 className="mt-2 text-base font-bold text-[#33485d]">{sighting.missingPersonName || 'Unassigned sighting'}</h2><p className="mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-[#788594]"><span className="flex items-center gap-1"><MapPin className="h-3.5 w-3.5" />{sighting.location}</span><span className="flex items-center gap-1"><Clock3 className="h-3.5 w-3.5" />{fmtDate(sighting.sightingDate)}</span></p><p className="mt-3 max-w-3xl text-sm leading-6 text-[#536579]">{sighting.description}</p><p className="mt-2 text-xs text-[#8d806e]">Reported by {sighting.reporterName || 'anonymous'} · {fmtTime(sighting.createdAt)}</p></div><div className="flex shrink-0 flex-wrap gap-2 md:w-36 md:flex-col"><select disabled={pending} value={sighting.status} onChange={(e) => onStatus(sighting.id, e.target.value as SightingStatusType)} className="field !py-2 text-xs" data-testid={`select-sighting-action-${sighting.id}`}>{Object.values(SightingStatus).map((status) => <option key={status} value={status}>{status}</option>)}</select><Link href={`/sightings/${sighting.id}`} className="inline-flex min-h-9 items-center justify-center gap-1 rounded-md border border-[#cfc6ad] text-xs font-bold text-[#536579]" data-testid={`link-sighting-${sighting.id}`}><Eye className="h-3.5 w-3.5" /> Open report</Link></div></div></article>; }

function Matches() {
  const [status, setStatus] = useState<ReviewStatus | undefined>(); const query = useListMatches({ reviewStatus: status, limit: 100 }); const update = useUpdateMatch(); const qc = useQueryClient();
  const review = (id: number, reviewStatus: ReviewStatus) => update.mutate({ id, data: { reviewStatus } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListMatchesQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); } });
  return <><PageTitle eyebrow="Assisted review" title="Possible matches" description="Ranked signals awaiting a trained human decision. A confidence score is not proof of identity." action={<select value={status ?? ''} onChange={(e) => setStatus((e.target.value || undefined) as ReviewStatus | undefined)} className="field sm:w-44" data-testid="select-match-status"><option value="">All reviews</option>{Object.values(ReviewStatus).map((s) => <option key={s} value={s}>{s}</option>)}</select>} /><QueryState loading={query.isLoading} error={query.isError} empty={!query.isLoading && !query.isError && !(query.data ?? []).length} onRetry={() => query.refetch()}><div className="overflow-hidden rounded-xl border border-[#ddd6c6] bg-[#fffdf8]"><div className="scroll-thin overflow-x-auto"><table className="data-table w-full min-w-[800px] text-left"><thead className="bg-[#f3f0e8] text-[11px] uppercase tracking-wider text-[#8d806e]"><tr><th className="px-5 py-3">Match</th><th className="px-5 py-3">Confidence</th><th className="px-5 py-3">Ranking</th><th className="px-5 py-3">Review</th><th className="px-5 py-3 text-right">Decision</th></tr></thead><tbody className="divide-y divide-[#e7e0d2]">{(query.data ?? []).map((match) => <tr key={match.id} data-testid={`row-match-${match.id}`}><td className="px-5 py-4"><p className="font-bold text-[#33485d]">{match.matchedPersonName}</p><p className="mono text-[10px] text-[#8d806e]">Sighting {match.sightingId ? `#${match.sightingId}` : 'unlinked'}</p></td><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="h-2 w-24 rounded-full bg-[#e8e4d9]"><div className={cx('h-full rounded-full', match.confidenceScore >= 80 ? 'bg-[#4c8b69]' : 'bg-[#d6a84b]')} style={{ width: `${match.confidenceScore}%` }} /></div><span className="mono text-xs font-bold text-[#536579]">{match.confidenceScore.toFixed(1)}%</span></div></td><td className="px-5 py-4 mono text-xs text-[#788594]">#{match.ranking}</td><td className="px-5 py-4"><StatusPill value={match.reviewStatus} /></td><td className="px-5 py-4"><div className="flex justify-end gap-2"><Button variant="quiet" className="!min-h-8 !px-2 text-xs" disabled={update.isPending} onClick={() => review(match.id, ReviewStatus.Dismissed)} data-testid={`button-dismiss-match-${match.id}`}><XCircle className="h-3.5 w-3.5" /> Dismiss</Button><Button variant="gold" className="!min-h-8 !px-2 text-xs" disabled={update.isPending} onClick={() => review(match.id, ReviewStatus.Confirmed)} data-testid={`button-confirm-match-${match.id}`}><Check className="h-3.5 w-3.5" /> Confirm</Button></div></td></tr>)}</tbody></table></div></div></QueryState></>;
}

function Alerts() {
  const query = useListAlerts(); const update = useUpdateAlert(); const qc = useQueryClient(); const updateAlert = (id: number, status: AlertStatus) => update.mutate({ id, data: { status } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAlertsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); } });
  return <><PageTitle eyebrow="Priority queue" title="Review alerts" description="Alerts are generated from review signals and require investigator action before they are considered meaningful." /><QueryState loading={query.isLoading} error={query.isError} empty={!query.isLoading && !query.isError && !(query.data ?? []).length} onRetry={() => query.refetch()}><div className="space-y-3">{(query.data ?? []).map((alert) => <AlertRow key={alert.id} alert={alert} update={updateAlert} pending={update.isPending} />)}</div></QueryState></>;
}
function AlertRow({ alert, update, pending }: { alert: Alert; update: (id: number, status: AlertStatus) => void; pending: boolean }) { return <article className="rounded-xl border border-[#e1c7bd] bg-[#fffaf6] p-5" data-testid={`card-alert-${alert.id}`}><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-[#f5dfd9] text-[#a6473d]"><Bell className="h-5 w-5" /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><StatusPill value={alert.status} /><span className="mono text-[10px] text-[#8d806e]">AL-{String(alert.id).padStart(5, '0')}</span></div><h2 className="mt-2 font-bold text-[#33485d]">{alert.missingPersonName}</h2><p className="mt-1 text-sm text-[#68798a]">{alert.location || 'Location not provided'} · Confidence <strong className="text-[#a6473d]">{alert.confidenceScore.toFixed(1)}%</strong></p></div><div className="flex flex-wrap gap-2 sm:justify-end"><Button variant="quiet" className="!min-h-9 !px-3 text-xs" disabled={pending} onClick={() => update(alert.id, AlertStatus.Under_Review)} data-testid={`button-review-alert-${alert.id}`}>Review</Button><Button variant="gold" className="!min-h-9 !px-3 text-xs" disabled={pending} onClick={() => update(alert.id, AlertStatus.Confirmed)} data-testid={`button-confirm-alert-${alert.id}`}><Check className="h-3.5 w-3.5" /> Confirm</Button><Button variant="outline" className="!min-h-9 !px-3 text-xs" disabled={pending} onClick={() => update(alert.id, AlertStatus.Dismissed)} data-testid={`button-dismiss-alert-${alert.id}`}>Dismiss</Button></div></div></article>; }

function ActivityPage() { const query = useGetDashboardActivity(); return <><PageTitle eyebrow="Traceability" title="Activity history" description="A chronological record of changes made in the Sentinel operations room." /><div className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><QueryState loading={query.isLoading} error={query.isError} empty={!query.isLoading && !query.isError && !(query.data ?? []).length} onRetry={() => query.refetch()}><ActivityList items={query.data ?? []} /></QueryState></div></>; }

function Profile() { const user = useMemo(() => { try { return JSON.parse(localStorage.getItem('sentinel_user') ?? 'null'); } catch { return null; } }, []); return <><PageTitle eyebrow="Account" title="Profile" description="Your Sentinel access identity and workspace permissions." /><div className="max-w-2xl rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6 sm:p-8"><div className="flex items-center gap-4 border-b border-[#e7e0d2] pb-6"><span className="flex h-16 w-16 items-center justify-center rounded-full bg-[#d6a84b] text-xl font-bold text-[#172941]">{initials(user?.name)}</span><div><h2 className="text-xl font-bold text-[#18304d]">{user?.name ?? 'Sentinel user'}</h2><p className="mt-1 text-sm text-[#68798a]">{user?.email ?? 'Signed-in staff account'}</p></div></div><dl className="mt-6 grid gap-5 sm:grid-cols-2"><div><dt className="eyebrow text-[#a17a2b]">Role</dt><dd className="mt-2 font-semibold text-[#33485d]">{user?.role ?? UserRole.INVESTIGATOR}</dd></div><div><dt className="eyebrow text-[#a17a2b]">Access state</dt><dd className="mt-2 flex items-center gap-2 font-semibold text-[#367051]"><span className="h-2 w-2 rounded-full bg-[#4c8b69]" /> Active</dd></div></dl><div className="mt-8 flex gap-3 rounded-lg bg-[#f3f0e8] p-4 text-sm text-[#68798a]"><LockKeyhole className="h-5 w-5 shrink-0 text-[#a17a2b]" /> Staff activity is recorded to preserve a clear review trail.</div></div></>; }

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const [, setLocation] = useLocation(); const login = useLogin(); const register = useRegister(); const [form, setForm] = useState(mode === 'login' ? { email: '', password: '' } : { name: '', email: '', password: '' }); const [error, setError] = useState('');
  const set = (key: string) => (value: string) => setForm((current) => ({ ...current, [key]: value })); const submit = (e: FormEvent) => { e.preventDefault(); setError(''); const onSuccess = (result: { token: string; user: { role?: string } }) => { localStorage.setItem('sentinel_token', result.token); localStorage.setItem('sentinel_user', JSON.stringify(result.user)); setLocation(result.user.role === 'ADMIN' || result.user.role === 'INVESTIGATOR' ? '/dashboard' : '/'); }; if (mode === 'login') login.mutate({ data: form as { email: string; password: string } }, { onSuccess, onError: () => setError('Those credentials were not accepted. Check your details and try again.') }); else register.mutate({ data: form as { name: string; email: string; password: string } }, { onSuccess, onError: () => setError('We could not create this account. The email may already be in use.') }); };
  const pending = login.isPending || register.isPending;
  return <div className="noise grid min-h-[100dvh] bg-[#18304d] lg:grid-cols-[.8fr_1.2fr]"><div className="hidden flex-col justify-between bg-[#142a44] p-10 text-[#f7f1df] lg:flex"><Logo light /><div><p className="eyebrow text-[#d6a84b]">Private workspace</p><h1 className="mt-5 max-w-sm text-5xl font-bold leading-[.96] tracking-[-.06em]">A clear view of the work that matters.</h1><p className="mt-6 max-w-sm leading-7 text-[#b8c4cd]">Sentinel gives authorized teams one quiet place to review cases, sightings, and possible matches.</p></div><p className="mono text-[10px] text-[#8295a5]">AUTHORIZED ACCESS ONLY · SENTINEL OPS</p></div><div className="flex items-center justify-center bg-[#faf8f1] p-5 sm:p-10"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Logo /></div><p className="eyebrow text-[#a17a2b]">{mode === 'login' ? 'Staff access' : 'New staff account'}</p><h1 className="mt-3 text-4xl font-bold tracking-[-.05em] text-[#18304d]">{mode === 'login' ? 'Welcome back.' : 'Create your access.'}</h1><p className="mt-3 text-sm text-[#68798a]">{mode === 'login' ? 'Sign in to continue to the operations room.' : 'Use your organization email to request a Sentinel account.'}</p><form onSubmit={submit} className="mt-8 space-y-5">{mode === 'register' && <Field label="Name" name="name" value={(form as { name: string }).name} onChange={set('name')} required />}{mode === 'register' && <Field label="Email" name="email" type="email" value={form.email} onChange={set('email')} required />}{mode === 'login' && <Field label="Email" name="email" type="email" value={form.email} onChange={set('email')} required />}{<Field label="Password" name="password" type="password" value={form.password} onChange={set('password')} required />}{error && <p className="rounded-md bg-[#fbefec] p-3 text-sm text-[#91463e]" data-testid="status-auth-error">{error}</p>}<Button type="submit" className="w-full" disabled={pending} data-testid={`button-submit-${mode}`}>{pending ? <Loader2 className="h-4 w-4 animate-spin" /> : <LogIn className="h-4 w-4" />}{mode === 'login' ? 'Sign in' : 'Create account'}</Button></form><p className="mt-7 text-center text-sm text-[#68798a]">{mode === 'login' ? <>Need an account? <Link href="/register" className="font-bold text-[#8b6b2a]" data-testid="link-register">Register</Link></> : <>Already have access? <Link href="/login" className="font-bold text-[#8b6b2a]" data-testid="link-signin">Sign in</Link></>}</p><Link href="/" className="mt-8 block text-center text-xs font-semibold text-[#8d806e]" data-testid="link-auth-home">Return to public site</Link></div></div></div>;
}

function SightingDetail() { const { id } = useParams<{ id: string }>(); const query = useGetSighting(Number(id)); return <><Link href="/sightings" className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-[#68798a]" data-testid="link-back-sightings"><ArrowLeft className="h-4 w-4" /> Back to sightings</Link><PageTitle eyebrow="Sighting report" title={`Report SG-${String(id).padStart(6, '0')}`} /><QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{query.data && <div className="rounded-xl border border-[#ddd6c6] bg-[#fffdf8] p-6"><SightingRow sighting={query.data} onStatus={() => undefined} pending={false} /></div>}</QueryState></>; }
function CaseEditRoute() { const { id } = useParams<{ id: string }>(); return <StaffShell><CaseForm editId={Number(id)} /></StaffShell>; }

function PublicOrStaffRouter() {
  return <Switch>
    <Route path="/" component={Landing} /><Route path="/missing-persons" component={Directory} /><Route path="/missing-persons/:id" component={CaseDetail} /><Route path="/report-sighting" component={ReportSighting} /><Route path="/photo-search" component={PhotoSearch} /><Route path="/login" component={() => <AuthPage mode="login" />} /><Route path="/register" component={() => <AuthPage mode="register" />} />
    <Route path="/dashboard"><StaffShell><Dashboard /></StaffShell></Route><Route path="/cases"><StaffShell><Cases /></StaffShell></Route><Route path="/cases/new"><StaffShell><CaseForm /></StaffShell></Route><Route path="/cases/:id" component={CaseEditRoute} /><Route path="/sightings"><StaffShell><Sightings /></StaffShell></Route><Route path="/sightings/:id"><StaffShell><SightingDetail /></StaffShell></Route><Route path="/matches"><StaffShell><Matches /></StaffShell></Route><Route path="/alerts"><StaffShell><Alerts /></StaffShell></Route><Route path="/activity"><StaffShell><ActivityPage /></StaffShell></Route><Route path="/profile"><StaffShell><Profile /></StaffShell></Route>
    <Route><div className="min-h-[100dvh] bg-[#faf8f1]"><PublicHeader /><main className="mx-auto max-w-xl px-5 py-28 text-center"><Siren className="mx-auto h-10 w-10 text-[#a17a2b]" /><h1 className="mt-5 text-4xl font-bold text-[#18304d]">This page is not on our map.</h1><p className="mt-3 text-[#68798a]">The address may have changed or never existed.</p><Link href="/" className="mt-8 inline-flex min-h-11 items-center gap-2 rounded-md bg-[#18304d] px-5 text-sm font-bold text-[#f7f1df]" data-testid="link-not-found-home">Return home <ArrowRight className="h-4 w-4 text-[#d6a84b]" /></Link></main></div></Route>
  </Switch>;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><PublicOrStaffRouter /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;